-- Product update, 26 Nov 2026: refreshed copy and images for the existing watches, the 11 new round watches, and the Shape link (rectangular <-> round).
-- Safe to re-run (upserts by slug). Existing rows keep their LIVE stock and specs; Hindi fields that are blank in the sheet keep their current text.
alter table products add column if not exists tags jsonb default '[]'::jsonb, add column if not exists hindi_line text, add column if not exists tagline_hi text, add column if not exists description_hi text, add column if not exists long_description_hi text, add column if not exists stock_mode text default 'in_stock', add column if not exists video text, add column if not exists cover_first boolean default false;
alter table products add column if not exists shape text default 'rect', add column if not exists shape_link text;

-- Dhruv Night (YG-DHR-BK-BK)
insert into products(slug,name,sku,tagline,hindi_line,tags,case_color,strap_color,price,compare_price,stock,stock_mode,weight_g,description,long_description,tagline_hi,description_hi,long_description_hi,features,seo_title,seo_description,images,video,featured,active,sort,edition_total,edition_sold,collection_id,specs)
select $q$dhruv-night$q$,$q$Dhruv Night$q$,$q$YG-DHR-BK-BK$q$,$q$Be the fixed point in a turning world.$q$,$q$अचल ध्रुव$q$,$q$["Bestseller"]$q$::jsonb,$q$Black$q$,$q$Black$q$,2999,5999,50,$q$in_stock$q$,85,$q$Stillness at its darkest. Black case, black strap, an embossed navy compass dial. Japanese quartz.$q$,$q$Stillness at its darkest. A black case holds a deep navy dial, where a compass rose and the seven sages stand in raised gold, as quiet and as certain as the star they follow. A black tonneau case, with a deep and even finish. The black silicone strap is soft, light and moulded to sit flush against the case. Within is an accurate Japanese quartz movement. Dhruv Night belongs to Dhruv, one realm of the Yugastra sky: a timeless piece, made to be kept and not replaced.$q$,$q$घूमते संसार में, स्वयं अचल बिंदु बनिए।$q$,$q$गहनतम अंधकार में स्थिरता। श्याम आवरण, श्याम पट्टा, उभरे हुए नील डायल पर दिशासूचक। जापानी क्वार्ट्ज़।$q$,$q$गहनतम अंधकार में स्थिरता। श्याम टोन्यू आवरण, गहरी और समरूप सज्जा के साथ। श्याम सिलिकॉन पट्टा कोमल और हल्का है, और आवरण से सटकर बैठने के लिए ढला है। भीतर एक सटीक जापानी क्वार्ट्ज़ गति-तंत्र है। Dhruv Night युगास्त्र के आकाश के एक लोक की कृति है: कालातीत, सहेजने के लिए रची गई, बदले जाने के लिए नहीं।$q$,$q$["Embossed navy dial with raised gold detail", "Japanese quartz movement", "Black tonneau case, Black silicone strap", "1-year warranty", "Water resistant to 5 ATM (50 m)"]$q$::jsonb,$q$Dhruv Night · Dhruv Collection | YUGASTRA$q$,$q$Constancy, in black. Dhruv Night: black case, black strap, an embossed navy compass dial. Japanese quartz, 1-year warranty. From YUGASTRA, the weapon of timelessness. ₹5,999.$q$,$q$["https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-DHR-BK-BK-1.png", "https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-DHR-BK-BK-2.png", "https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-DHR-BK-BK-3.png", "https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-DHR-BK-BK-4.png", "https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-DHR-BK-BK-5.png", "https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-DHR-BK-BK-6.png"]$q$::jsonb,null,true,true,1,0,0,c.id,'{}'::jsonb from collections c where c.slug='dhruv'
on conflict (slug) do update set name=excluded.name,sku=excluded.sku,tagline=excluded.tagline,hindi_line=coalesce(excluded.hindi_line,products.hindi_line),tags=excluded.tags,case_color=excluded.case_color,strap_color=excluded.strap_color,price=excluded.price,compare_price=excluded.compare_price,stock_mode=excluded.stock_mode,weight_g=excluded.weight_g,description=excluded.description,long_description=excluded.long_description,tagline_hi=coalesce(excluded.tagline_hi,products.tagline_hi),description_hi=coalesce(excluded.description_hi,products.description_hi),long_description_hi=coalesce(excluded.long_description_hi,products.long_description_hi),features=excluded.features,seo_title=excluded.seo_title,seo_description=excluded.seo_description,images=excluded.images,video=coalesce(excluded.video,products.video),featured=excluded.featured,active=excluded.active,sort=excluded.sort,collection_id=excluded.collection_id;

