select $q$vyom-nebula$q$,$q$Vyom Nebula$q$,$q$YG-VYO-BK-BK-RD$q$,$q$Where the stars begin.$q$,null,$q$[]$q$::jsonb,$q$Matte black$q$,$q$Black$q$,2999,5999,50,$q$in_stock$q$,60,$q$A round matte black case, a black leather strap and a deep green dial with a gold sphere and three orbit rings. VYOM Nebula, the Realm of Space.$q$,$q$A nebula is the dark, slow cloud in which stars are first made. Here it is a matte black case and a black leather strap, closing in on a deep green dial, so that nothing competes with what sits at the centre: a striated gold sphere, three thin orbits and nine small gold beads. Only the gold is allowed to catch the light. It is the quietest of the VYOM watches, the sky before it has any names.$q$,null,null,null,$q$["Deep green dial with a gold sphere and three orbit rings", "Japanese quartz movement", "Round 40 mm case, matte black finish", "22 mm black leather strap, stitched edges", "1-year warranty"]$q$::jsonb,$q$Vyom Nebula · Vyom Collection | YUGASTRA$q$,$q$Vyom Nebula in a round 40 mm case: matte black case, black leather strap. Japanese quartz, 1-year warranty. From YUGASTRA, the weapon of timelessness. ₹2,999.$q$,$q$["https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-VYO-BK-BK-RD-3.png", "https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-VYO-BK-BK-RD-4.png", "https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-VYO-BK-BK-RD-7.png"]$q$::jsonb,null,false,true,308,0,0,c.id,$q${"Collection": "VYOM", "Movement": "Japanese quartz", "Case": "Matte black, round, 40 mm", "Strap": "Black leather, 22 mm", "Dial": "Embossed dark green dial", "Weight": "Approx. 60 g", "Warranty": "1 year", "Strap width": "22 mm"}$q$::jsonb from collections c where c.slug='vyom'
on conflict (slug) do update set name=excluded.name,sku=excluded.sku,tagline=excluded.tagline,hindi_line=coalesce(excluded.hindi_line,products.hindi_line),tags=excluded.tags,case_color=excluded.case_color,strap_color=excluded.strap_color,price=excluded.price,compare_price=excluded.compare_price,stock_mode=excluded.stock_mode,weight_g=excluded.weight_g,description=excluded.description,long_description=excluded.long_description,tagline_hi=coalesce(excluded.tagline_hi,products.tagline_hi),description_hi=coalesce(excluded.description_hi,products.description_hi),long_description_hi=coalesce(excluded.long_description_hi,products.long_description_hi),features=excluded.features,seo_title=excluded.seo_title,seo_description=excluded.seo_description,images=excluded.images,video=coalesce(excluded.video,products.video),featured=excluded.featured,active=excluded.active,sort=excluded.sort,collection_id=excluded.collection_id;

