select $q$vyom-comet$q$,$q$Vyom Comet$q$,$q$YG-VYO-GD-BK-RD$q$,$q$One bright pass across the dark.$q$,null,$q$[]$q$::jsonb,$q$Gold$q$,$q$Black$q$,2999,5999,50,$q$in_stock$q$,60,$q$A round gold-coloured case, a black leather strap and a deep green dial with a gold sphere and three orbit rings. VYOM Comet, the Realm of Space.$q$,$q$A comet crosses the sky on a long orbit and returns, on time, years later. Comet takes that idea literally: the orbits are already on the dial, with nine gold beads along them, and the soft gold-coloured case is the light that passes. The black leather strap holds it all in the dark. It is the warmest of the round VYOM watches, for the wearer who likes a little light in the night.$q$,null,null,null,$q$["Deep green dial with a gold sphere and three orbit rings", "Japanese quartz movement", "Round 40 mm case, gold finish", "22 mm black leather strap, stitched edges", "1-year warranty"]$q$::jsonb,$q$Vyom Comet · Vyom Collection | YUGASTRA$q$,$q$Vyom Comet in a round 40 mm case: gold case, black leather strap. Japanese quartz, 1-year warranty. From YUGASTRA, the weapon of timelessness. ₹2,999.$q$,$q$["https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-VYO-GD-BK-RD-3.png", "https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-VYO-GD-BK-RD-4.png", "https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-VYO-GD-BK-RD-7.png"]$q$::jsonb,null,false,true,309,0,0,c.id,$q${"Collection": "VYOM", "Movement": "Japanese quartz", "Case": "Gold, round, 40 mm", "Strap": "Black leather, 22 mm", "Dial": "Embossed dark green dial", "Weight": "Approx. 60 g", "Warranty": "1 year", "Strap width": "22 mm"}$q$::jsonb from collections c where c.slug='vyom'
