-- Shape: every SKU ending -RD is a round realm watch; links join the rectangular and round version of the same watch.
update products set shape='round' where sku like '%-RD';
update products set shape='rect' where shape is null;
update products set shape_link='dhruv-night-ii' where slug='dhruv-night';
update products set shape_link='dhruv-night' where slug='dhruv-night-ii';
update products set shape_link='surya-eclipse-ii' where slug='surya-eclipse';
update products set shape_link='surya-eclipse' where slug='surya-eclipse-ii';
update products set shape_link='surya-radiance-ii' where slug='surya-radiance';
update products set shape_link='surya-radiance' where slug='surya-radiance-ii';
update products set shape_link='surya-sunrise-ii' where slug='surya-sunrise';
update products set shape_link='surya-sunrise' where slug='surya-sunrise-ii';
update products set shape_link='naksh-midnight-ii' where slug='naksh-midnight';
update products set shape_link='naksh-midnight' where slug='naksh-midnight-ii';
update products set shape_link='naksh-royal-ii' where slug='naksh-royal';
update products set shape_link='naksh-royal' where slug='naksh-royal-ii';
update products set shape_link='soma-crescent-ii' where slug='soma-crescent';
update products set shape_link='soma-crescent' where slug='soma-crescent-ii';
update products set shape_link='soma-new-moon-ii' where slug='soma-new-moon';
update products set shape_link='soma-new-moon' where slug='soma-new-moon-ii';
update products set cover_first=true where shape='round';
notify pgrst, 'reload schema';
